ALTER TABLE public.k3_settings ADD COLUMN week_enabled boolean NOT NULL DEFAULT false, ADD COLUMN month_enabled boolean NOT NULL DEFAULT false, ADD COLUMN period_effective_from date, ADD COLUMN period_deadlines jsonb NOT NULL DEFAULT '{}'::jsonb;
CREATE TABLE public.k3_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,period_type text NOT NULL CHECK(period_type IN('week','month')),period_start date NOT NULL,period_end date NOT NULL,name text NOT NULL,description text,expected_result text,kpi_target numeric CHECK(kpi_target>=0),kpi_unit text,due_date date,department_id uuid REFERENCES public.biz_departments(id),revision bigint NOT NULL DEFAULT 0,request_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_key));
GRANT SELECT ON public.k3_goals TO authenticated; GRANT ALL ON public.k3_goals TO service_role; ALTER TABLE public.k3_goals ENABLE ROW LEVEL SECURITY;
CREATE POLICY k3_goal_own ON public.k3_goals FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
CREATE TABLE public.k3_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),goal_id uuid NOT NULL REFERENCES public.k3_goals(id),user_id uuid NOT NULL,name text NOT NULL,kpi_target numeric CHECK(kpi_target>=0),kpi_unit text,start_date date,due_date date,note text,manual_progress smallint CHECK(manual_progress BETWEEN 0 AND 100),progress_source text,revision bigint NOT NULL DEFAULT 0,request_key uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_key));
GRANT SELECT ON public.k3_actions TO authenticated; GRANT ALL ON public.k3_actions TO service_role; ALTER TABLE public.k3_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY k3_action_own ON public.k3_actions FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
ALTER TABLE public.k3_tasks ADD COLUMN action_id uuid REFERENCES public.k3_actions(id), ADD COLUMN is_unscheduled boolean NOT NULL DEFAULT false, ADD COLUMN original_work_date date;
CREATE INDEX k3_task_action ON public.k3_tasks(action_id); CREATE INDEX k3_goal_period ON public.k3_goals(user_id,period_type,period_start); CREATE INDEX k3_action_goal ON public.k3_actions(goal_id);
CREATE TABLE public.k3_period_summaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,period_type text NOT NULL CHECK(period_type IN('week','month')),period_start date NOT NULL,fingerprint text NOT NULL,note text,confirmed_at timestamptz NOT NULL DEFAULT now(),snapshot jsonb NOT NULL,department_id uuid REFERENCES public.biz_departments(id),UNIQUE(user_id,period_type,period_start,fingerprint));
GRANT SELECT ON public.k3_period_summaries TO authenticated; GRANT ALL ON public.k3_period_summaries TO service_role; ALTER TABLE public.k3_period_summaries ENABLE ROW LEVEL SECURITY;
CREATE POLICY k3_period_summary_own ON public.k3_period_summaries FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
CREATE TABLE public.k3_period_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,period_type text NOT NULL CHECK(period_type IN('week','month')),period_start date NOT NULL,goal_id uuid REFERENCES public.k3_goals(id),action_id uuid REFERENCES public.k3_actions(id),author_id uuid NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.k3_period_comments TO authenticated; GRANT ALL ON public.k3_period_comments TO service_role; ALTER TABLE public.k3_period_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY k3_period_comment_own ON public.k3_period_comments FOR SELECT TO authenticated USING(user_id=auth.uid() OR author_id=auth.uid());
CREATE TABLE public.k3_plan_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,goal_id uuid REFERENCES public.k3_goals(id),action_id uuid REFERENCES public.k3_actions(id),actor_id uuid NOT NULL,action text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.k3_plan_events TO authenticated; GRANT ALL ON public.k3_plan_events TO service_role; ALTER TABLE public.k3_plan_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY k3_plan_event_own ON public.k3_plan_events FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.k3_can(auth.uid(),'k3.use'));
CREATE FUNCTION public.k3_period_start(_type text,_date date) RETURNS date LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$BEGIN IF _type='week' THEN RETURN _date-(extract(isodow FROM _date)::int-1); ELSIF _type='month' THEN RETURN date_trunc('month',_date)::date; ELSE RAISE EXCEPTION 'Chu kỳ 3K không hợp lệ.'; END IF; END$$;
CREATE FUNCTION public.k3_period_end(_type text,_date date) RETURNS date LANGUAGE sql IMMUTABLE SET search_path=public AS $$SELECT CASE WHEN _type='week' THEN public.k3_period_start(_type,_date)+6 ELSE (public.k3_period_start(_type,_date)+interval '1 month'-interval '1 day')::date END$$;
CREATE FUNCTION private.k3_period_write_guard(_type text,_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE s public.k3_settings; BEGIN PERFORM private.k3_write_guard(greatest(_date,(SELECT effective_from FROM public.k3_settings WHERE id))); SELECT * INTO s FROM public.k3_settings WHERE id FOR SHARE; IF _type NOT IN('week','month') OR NOT (CASE WHEN _type='week' THEN s.week_enabled ELSE s.month_enabled END) OR s.period_effective_from IS NULL OR public.k3_period_end(_type,_date)<s.period_effective_from THEN RAISE EXCEPTION 'Chu kỳ 3K chưa được kích hoạt hoặc chưa đến ngày áp dụng.'; END IF; END$$;
CREATE FUNCTION public.k3_period_settings_save(_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE s public.k3_settings; old public.k3_settings; x record; dl jsonb:=coalesce(_payload->'period_deadlines','{}'::jsonb); BEGIN IF NOT public.k3_can(auth.uid(),'k3.settings') THEN RAISE EXCEPTION 'Bạn không có quyền cấu hình 3K.'; END IF; SELECT * INTO old FROM public.k3_settings WHERE id FOR UPDATE;
IF (coalesce((_payload->>'week_enabled')::boolean,false) OR coalesce((_payload->>'month_enabled')::boolean,false)) AND nullif(_payload->>'period_effective_from','') IS NULL THEN RAISE EXCEPTION 'Cần chọn ngày bắt đầu áp dụng Tuần/Tháng.'; END IF;
FOR x IN SELECT * FROM jsonb_each(dl) LOOP IF x.key NOT IN('week_plan','week_summary','month_plan','month_summary') OR (x.value->>'offset')::int IS NULL OR (x.value->>'offset')::int NOT BETWEEN -31 AND 62 OR nullif(x.value->>'time','') IS NULL OR nullif(x.value->>'effective_from','')::date IS NULL THEN RAISE EXCEPTION 'Deadline cần ngày tương đối, giờ và ngày hiệu lực hợp lệ.'; END IF; PERFORM (x.value->>'time')::time; END LOOP;
UPDATE public.k3_settings SET week_enabled=coalesce((_payload->>'week_enabled')::boolean,false),month_enabled=coalesce((_payload->>'month_enabled')::boolean,false),period_effective_from=nullif(_payload->>'period_effective_from','')::date,period_deadlines=dl,updated_at=now(),updated_by=auth.uid() WHERE id RETURNING * INTO s;
INSERT INTO public.k3_settings_log(changed_by,snapshot) VALUES(auth.uid(),jsonb_build_object('old',to_jsonb(old),'new',to_jsonb(s))); RETURN to_jsonb(s); END$$;
CREATE FUNCTION public.k3_period_config_read() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT to_jsonb(s) FROM public.k3_settings s WHERE id AND auth.uid() IS NOT NULL$$;
REVOKE ALL ON FUNCTION public.k3_period_start(text,date),public.k3_period_end(text,date),public.k3_period_settings_save(jsonb),public.k3_period_config_read(),private.k3_period_write_guard(text,date) FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION private.k3_period_write_guard(text,date) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.k3_period_start(text,date),public.k3_period_end(text,date),public.k3_period_settings_save(jsonb),public.k3_period_config_read() TO authenticated;